const raw = $input.first().json;
const data = (raw.body && raw.body.payload) ? raw.body.payload : (raw.body || raw);

const studentName = data.student_name || 'Student';
const studentEmail = data.student_email || (raw.body && raw.body.student_email);
const mentorName = data.mentor_name || 'Mentor';
const scheduledAt = data.scheduled_at || '';
const timezone = data.timezone || 'Asia/Kolkata';
const meetLink = data.meet_link || 'https://meet.google.com';
const briefSummary = data.pre_call_brief_summary || '';
const blocker = data.current_blocker || '';
const desiredOutcome = data.desired_outcome || '';
const portalUrl = data.portal_url || 'https://mentor-connect-mesa.vercel.app/preparation';

// Format questions
let questionsText = '';
if (Array.isArray(data.key_questions) && data.key_questions.length > 0) {
  questionsText = data.key_questions.map((q, idx) => `  ${idx + 1}. ${q}`).join('\n');
} else if (typeof data.key_questions === 'string') {
  questionsText = `  • ${data.key_questions}`;
}

// Format agenda
let agendaText = '';
if (Array.isArray(data.suggested_agenda) && data.suggested_agenda.length > 0) {
  agendaText = data.suggested_agenda.map(a => `  • ${a}`).join('\n');
}

// Format checklist
let checklistText = '';
if (Array.isArray(data.checklist) && data.checklist.length > 0) {
  checklistText = data.checklist.map(c => `  [ ] ${c}`).join('\n');
}

// Format date nicely
let dateDisplay = scheduledAt;
try {
  const d = new Date(scheduledAt);
  dateDisplay = d.toLocaleString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZoneName: 'short'
  });
} catch(e) {}

const subject = `Confirmed: Mesa Mentorship with ${mentorName} on ${dateDisplay}`;

const message = `Hello ${studentName},\n\nYour mentorship session with ${mentorName} is confirmed!\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nSESSION DETAILS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n• Date & Time: ${dateDisplay} (${timezone})\n• Duration: 45 Minutes\n• Google Meet: ${meetLink}\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nPRE-CALL PREPARATION BRIEF\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n${briefSummary ? `SUMMARY:\n${briefSummary}\n\n` : ''}${blocker ? `CURRENT BLOCKER:\n${blocker}\n\n` : ''}${desiredOutcome ? `DESIRED OUTCOME:\n${desiredOutcome}\n\n` : ''}${questionsText ? `3 KEY QUESTIONS TO COVER:\n${questionsText}\n\n` : ''}${agendaText ? `SUGGESTED 45-MINUTE AGENDA:\n${agendaText}\n\n` : ''}${checklistText ? `PREPARATION CHECKLIST:\n${checklistText}\n\n` : ''}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nACCESS YOUR INTERACTIVE BRIEF\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nYou can review, take notes, and track your action items directly on the Mesa portal:\n${portalUrl}\n\nBest regards,\nMesa School of Business Mentorship Team`;

return [{
  json: {
    student_email: studentEmail,
    student_name: studentName,
    mentor_name: mentorName,
    meet_link: meetLink,
    email_subject: subject,
    email_body: message,
    booking_id: data.booking_id,
    execution_id: $execution.id
  }
}];
